    char *candidate = NULL;
    size_t candidate_size = 0;
    size_t count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        count++;
        size_t len = strlen(buffer);
        char *temp = realloc(candidate, len + 1);
        if (!temp) {
            free(candidate);
            return NULL; // handle memory error
        }
        candidate = temp;
        strcpy(candidate, buffer);
        if (rand() % count == 0) {
            // With probability 1/count, select current string
            // No action needed, candidate already points to current string
        }
    }
    return candidate;
}
